import{cardImage,setImageSettings,mountImageEditor}from'./card-images.mjs';
import{mountScreenshot}from'./screenshot.mjs';
import{matchesCard,selectionPowerLabel}from'./search.mjs';
import{formationExtras,positionNote}from'./formation-view.mjs';
import{MODES,blank,fresh,powerOK,total,validState,validBuild,encodeShare,decodeShare}from'./core.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let disposeImport=null,disposeImageEditor=null;
let cards=[],byId,ids,state,view='formation',mode='nyan',tab='current',shared=[],selected=new Set(),filters={q:'',rarity:'',attribute:'',owned:false},picker=null;
const KEY='todiva-builder-v1',clone=v=>structuredClone(v),fmt=n=>n.toLocaleString('ja-JP')+'万';
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000)}
function persist(next=state){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true}catch{toast('保存できません。空き容量やブラウザ設定を確認し、バックアップしてください。');return false}}
function mutate(fn){const next=clone(state);fn(next);if(persist(next))render()}
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
function cardHTML(c,slot=null,actions='',extra=''){return`<article class="card"><div class="card-image-frame">${cardImage(c,'class="portrait"')}</div><div class="cardbody"><span class="badge">${esc(c.rarity)}</span> <span class="badge attr-${esc(c.attribute)}">${esc(c.attribute)}</span><h3>${esc(c.name)}</h3><div class="cardname">${esc(c.cardName)}</div>${slot?`<div class="power">${fmt(slot.power)}</div>${!state.owned[c.id]?'<div class="missing">未所持</div>':''}`:''}<div class="passive">${esc(c.skills?.passive||'パッシブ情報なし')}</div>${extra}<div class="row">${btn('詳細',`detail:${c.id}`)}${actions}</div></div></article>`}
function squadsHTML(s,editable=false){return s.map((row,i)=>`<section class="squad"><header class="row spread"><h2>第${i+1}班</h2><b>${fmt(total([row]))}</b></header><div class="grid">${row.map((slot,j)=>slot?cardHTML(byId.get(slot.id),slot,editable?btn('変更',`pick:${i}:${j}`)+btn('外す',`remove:${i}:${j}`):'',editable?`<div class="position-label">${j+1}枚目 · ${j<4?'前衛':'後衛'}</div>${positionNote(byId.get(slot.id),j)}<label>戦力（万）<input aria-label="第${i+1}班 ${j+1}枚目の戦力" type="number" min="1" max="9999" step="1" value="${slot.power}" data-slot="${i}:${j}"></label>`:''):`<button class="slot" ${editable?`data-action="pick:${i}:${j}"`:'disabled'}><strong>＋</strong><span>${j+1}枚目 · ${j<4?'前衛':'後衛'}${editable?' / カードを選択':''}</span></button>`).join('')}</div></section>`).join('')}
function filterHTML(){return`<div class="filters"><input id="search" type="search" placeholder="名前・よみがな・カード名・スキルで検索" aria-label="カード検索" value="${esc(filters.q)}"><select id="rarity" aria-label="レア度"><option value="">すべてのレア度</option>${['SSR','SR','R'].map(r=>`<option ${filters.rarity===r?'selected':''}>${r}</option>`).join('')}</select><select id="attribute" aria-label="属性"><option value="">すべての属性</option>${['緑','赤','青'].map(r=>`<option ${filters.attribute===r?'selected':''}>${r}</option>`).join('')}</select></div>${picker?`<label><input id="ownedOnly" type="checkbox" ${filters.owned?'checked':''}> 手持ちのみ</label>`:''}`}
function filtered(){return cards.filter(c=>(!filters.rarity||c.rarity===filters.rarity)&&(!filters.attribute||c.attribute===filters.attribute)&&(!(view==='owned'||picker&&filters.owned)||state.owned[c.id])&&matchesCard(c,filters.q))}
function catalogContent(){const list=filtered();return`<p class="muted">${list.length}枚${view==='owned'?' / 戦力は1〜9999、1＝1万':''}</p><div class="grid catalog">${list.map(c=>{const used=picker&&state.current[mode][picker.i].some((s,j)=>j!==picker.j&&s?.id===c.id);const action=picker?btn(used?'班内で使用中':'このカードを配置',`choose:${c.id}`,'primary',used?'disabled':''):state.owned[c.id]?`<label>戦力（万）<input type="number" min="1" max="9999" step="1" value="${state.owned[c.id]}" data-owned="${c.id}" aria-label="${esc(c.name)}の戦力"></label>${btn('所持解除',`unown:${c.id}`,'danger')}`:btn('手持ちに登録',`own:${c.id}`,'primary');return cardHTML(c,null,action,picker?`<div class="power">${esc(selectionPowerLabel(c.id,state.owned))}</div>`:'')}).join('')}</div>${list.length?'':`<div class="empty">${view==='owned'?'まだ手持ちがありません。図鑑でカードを登録してください。':'条件に合うカードがありません。'}</div>`}`}
function buildsHTML(list,isShared=false){return list.length?list.map(b=>`<article class="build"><div class="row spread"><h3>${esc(b.name)}</h3>${!isShared?`<label><input type="checkbox" data-select="${esc(b.id)}" ${selected.has(b.id)?'checked':''}> 共有</label>`:''}</div><small>${MODES[b.mode].label} · ${fmt(total(b.squads))}</small><div class="row">${btn('編成を見る',`${isShared?'shared':'build'}:${b.id}`)}${isShared?btn('自分のビルドへコピー',`copy:${b.id}`,'primary'):btn('編集用に読み込む',`load:${b.id}`)+btn('削除',`delete:${b.id}`,'danger')}</div></article>`).join(''):'<div class="empty">ビルドはまだありません。</div>'}
function render(){setImageSettings(state.imageSettings);picker=null;$('#nav').innerHTML=[['formation','編成'],['owned','手持ち'],['catalog','図鑑'],['help','ヘルプ']].map(([v,n])=>btn(n,`view:${v}`,view===v?'active':'')).join('');let html='';if(view==='formation'){html=`<h1>編成</h1><div class="row tabs">${[['current','現在の編成'],['saved','保存ビルド'],['shared','共有ビルド']].map(([t,n])=>btn(n,`tab:${t}`,tab===t?'active':'')).join('')}</div>`;if(tab==='current'){const s=state.current[mode];html+=`<div class="modes">${Object.entries(MODES).map(([m,o])=>btn(o.label,`mode:${m}`,m===mode?'active':'')).join('')}</div><div class="summary row spread"><div><small>総戦力</small><br><strong>${fmt(total(s))}</strong></div><span>${s.flat().filter(Boolean).length} / ${s.length*6}枚</span></div><div class="row">${btn('ビルドとして保存','save','primary')}${btn('編成をクリア','clear')}</div>${s.flat().some(Boolean)?'':'<p class="muted">＋をタップしてカードを配置。未所持カードでも編成できます。</p>'}${squadsHTML(s,true)}<div id="formationExtras">${formationExtras(s,byId)}</div>`}else if(tab==='saved')html+=`<div class="row spread"><p>${state.builds.length}件の保存ビルド</p>${btn('選択したビルドを共有','share','primary')}</div>${buildsHTML(state.builds)}`;else html+=`<p class="muted">共有リンクを開くとここに表示されます。共有時の戦力で閲覧できます。</p>${btn('共有リンクを読み込む','importLink')}${buildsHTML(shared,true)}`}
else if(view==='catalog'||view==='owned')html=`<div class="row spread"><h1>${view==='owned'?'手持ち':'カード図鑑'}</h1>${view==='owned'?btn('図鑑から登録','view:catalog','primary')+btn('スクショから登録','screenshot'):''}</div>${filterHTML()}<div id="results">${catalogContent()}</div>`;
else html=`<div class="help"><h1>ヘルプ・データ管理</h1><section><h2>最初の使い方</h2><p>図鑑から持っているカードを登録し、手持ち画面で戦力を入力します。編成画面の＋からカードを選び、名前を付けてビルドを保存しましょう。</p></section><section><h2>戦力と編成</h2><p>戦力は整数1〜9999の万単位です。125は125万。同一カードは1つの班に1枚まで、別の班には配置できます。班戦力・総戦力は入力値の合計で、ゲーム内の補正を再計算するものではありません。手持ちの戦力を変更しても、配置済み・保存済みの戦力は維持されます。</p><p>各班の1〜4枚目は前衛、5〜6枚目は後衛。エントリー系など増援時に発動するスキルは後衛配置で条件を確認してください。編成下部のプレビューで配置を確認でき、一番下ではスキル別の枚数を集計します。集計は所持スキル数であり、発動を保証するものではありません。</p></section><section><h2>保存と共有</h2><p>現在の編成は自動保存。ビルドとして保存すると、その時点の配置と戦力を残せます。保存ビルドの共有チェックで最大10件を選択できます。受信側は閲覧・コピーでき、未所持カードが表示されます。共有リンクは作成時点の内容で、後から編集しても変わりません。</p></section><section><h2>バックアップ・復元</h2><p>データはこのブラウザに保存されます。機種変更やブラウザデータ削除の前にバックアップしてください。復元すると手持ち・現在の編成・保存ビルドを置き換えます。</p><div class="row">${btn('バックアップを書き出す','backup','primary')}${btn('バックアップから復元','restore')}</div><input id="restoreFile" type="file" accept=".json,application/json" hidden></section><section><h2>カード情報について</h2><p>非公式の編成支援ツールです。収録${cards.length}枚。カード情報が未登録の場合は「情報なし」と表示します。</p><details class="skill-detail"><summary>出典情報</summary><p>カード情報の追加参照元：<a href="https://w.atwiki.jp/tokyodebunker/pages/11.html" target="_blank" rel="noopener">東京ディバンカー非公式アットウィキ</a>、<a href="https://tekuwiki.cloudfree.jp/全カード一覧/" target="_blank" rel="noopener">東京ディバンカー攻略wiki</a>。カード画像は参照元の外部URLを使用しており、表示できない場合があります。</p></details></section></div>`;$('#app').innerHTML=html}
function modal(html){disposeImageEditor?.();disposeImageEditor=null;disposeImport?.();disposeImport=null;$('#modalBody').innerHTML=`<div class="row spread modalhead"><b>東ディバ編成ビルダー</b>${btn('閉じる','close')}</div>${html}`;if(!$('#modal').open)$('#modal').showModal()}
function detail(id){const c=byId.get(Number(id));modal(`<div class="image-edit-preview">${cardImage(c)}</div>${btn('画像を調整',`imageEdit:${c.id}`)}<h2>${esc(c.name)}</h2><p>${esc(c.cardName)} · ${c.rarity} · ${c.attribute}</p><h3>${esc(c.attackerType||'アタッカー属性：情報なし')}</h3>${c.dataStatus!=='complete'?'<p class="muted">一部のカード情報は未登録です。</p>':''}<div class="stats">${Object.entries(c.initialStats).map(([k,v])=>`<div>${esc(k)} <b>${v}</b></div>`).join('')}</div>${[['unique','ユニークスキル'],['active','アクティブスキル'],['passive','パッシブスキル']].map(([k,n])=>`<h3>${n}</h3><p class="detailtext">${esc(c.skills?.[k]||'情報なし')}</p>`).join('')}<h3>リンクボーナス</h3><p>${esc(c.linkBonus||'情報なし')}</p><a href="${esc(c.sourceUrl)}" target="_blank" rel="noopener">Wikiで確認</a>`)}
function openPicker(i,j){picker={i:Number(i),j:Number(j)};filters={q:'',rarity:'',attribute:'',owned:false};modal(`<h2>第${+i+1}班 · ${+j+1}枚目（${+j<4?'前衛':'後衛'}）を選択</h2>${filterHTML()}<div id="results">${catalogContent()}</div>`)}
$('#modal').addEventListener('close',()=>{disposeImageEditor?.();disposeImageEditor=null;disposeImport?.();disposeImport=null});
function download(name,value){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const[a,x,y]=el.dataset.action.split(':');try{if(a==='imageEdit'){const c=byId.get(Number(x));modal('<div id="cardImageEditor"></div>');disposeImageEditor=mountImageEditor($('#cardImageEditor'),c,state.imageSettings?.[c.id],value=>{const next=clone(state);next.imageSettings??={};next.imageSettings[c.id]=value;if(persist(next)){render();detail(c.id);toast('画像調整を保存しました')}},()=>{const next=clone(state);if(next.imageSettings)delete next.imageSettings[c.id];if(persist(next)){render();detail(c.id);toast('元の画像に戻しました')}})}if(a==='close'){disposeImageEditor?.();disposeImageEditor=null;disposeImport?.();disposeImport=null;$('#modal').close();picker=null}if(a==='screenshot'){modal('<div id="screenshotImport"></div>');disposeImport=mountScreenshot($('#screenshotImport'),cards,values=>{const next=clone(state);Object.assign(next.owned,values);if(persist(next)){disposeImport?.();disposeImport=null;$('#modal').close();render();toast(Object.keys(values).length+'枚を手持ちに登録しました')}})}if(a==='view'){view=x;filters={q:'',rarity:'',attribute:'',owned:false};render()}if(a==='tab'){tab=x;render()}if(a==='mode'){mode=x;render()}if(a==='detail')detail(x);if(a==='pick')openPicker(x,y);if(a==='choose'){const c=Number(x),{i,j}=picker;if(state.current[mode][i].some((s,k)=>k!==j&&s?.id===c))throw Error('同じ班に同一カードは配置できません');mutate(s=>s.current[mode][i][j]={id:c,power:s.owned[c]||1});$('#modal').close()}if(a==='remove')mutate(s=>s.current[mode][x][y]=null);if(a==='own'){mutate(s=>s.owned[x]=1);toast('手持ちに登録しました。戦力を設定してください。')}if(a==='unown'&&confirm('手持ち登録を解除しますか？配置済みのカードは残ります。'))mutate(s=>delete s.owned[x]);if(a==='clear'&&confirm('現在の編成をクリアしますか？保存ビルドは残ります。'))mutate(s=>s.current[mode]=blank(mode));if(a==='save')modal(`<h2>ビルドを保存</h2><form id="saveForm"><label>ビルド名<input name="name" required maxlength="80" placeholder="例：ボス用 速攻編成" style="width:100%"></label><p>${MODES[mode].label} · ${fmt(total(state.current[mode]))}</p><button class="primary">保存</button></form>`);
if(a==='load'){const b=state.builds.find(b=>b.id===x);if(confirm('現在の編成をこのビルドに置き換えますか？')){mode=b.mode;tab='current';mutate(s=>s.current[mode]=clone(b.squads))}}if(a==='delete'&&confirm('保存ビルドを削除しますか？')){selected.delete(x);mutate(s=>s.builds=s.builds.filter(b=>b.id!==x))}if(a==='build'||a==='shared'){const b=(a==='build'?state.builds:shared).find(b=>b.id===x);modal(`<h2>${esc(b.name)}</h2><p>${MODES[b.mode].label} · ${fmt(total(b.squads))}</p>${squadsHTML(b.squads)}${formationExtras(b.squads,byId)}`)}if(a==='copy'){const b=shared.find(b=>b.id===x);mutate(s=>s.builds.push({...clone(b),id:crypto.randomUUID(),name:b.name.slice(0,74)+'（コピー）',updatedAt:new Date().toISOString()}));toast('保存ビルドへコピーしました')}
if(a==='share'){const list=state.builds.filter(b=>selected.has(b.id));if(!list.length||list.length>10)throw Error('共有するビルドを1〜10件選んでください');const token=await encodeShare(list);const url=location.href.split('#')[0]+'#share='+token;if(url.length>12000)throw Error('リンクが長すぎます。共有するビルドを減らしてください');modal(`<h2>${list.length}件のビルドを共有</h2><p>このリンクを相手に送ってください。</p><textarea id="shareURL" readonly aria-label="共有リンク">${esc(url)}</textarea><div class="row">${btn('リンクをコピー','copyURL','primary')}${btn('端末の共有メニュー','nativeShare')}</div>`)}if(a==='copyURL'){try{await navigator.clipboard.writeText($('#shareURL').value);toast('リンクをコピーしました')}catch{$('#shareURL').select();toast('リンクを選択しました。手動でコピーしてください。')}}if(a==='nativeShare'){if(navigator.share)await navigator.share({title:'東ディバ共有ビルド',url:$('#shareURL').value});else toast('この端末では共有メニューを使えません。リンクをコピーしてください。')}if(a==='importLink')modal('<h2>共有リンクを読み込む</h2><form id="linkForm"><label>共有URL<textarea name="url" required></textarea></label><button class="primary">読み込む</button></form>');if(a==='backup')download('todiva-backup-'+new Date().toISOString().slice(0,10)+'.json',state);if(a==='restore')$('#restoreFile').click();}catch(err){if(err.name!=='AbortError')toast(err.message)}});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.owned||t.dataset.slot){const p=Number(t.value);if(powerOK(p)){const next=clone(state);if(t.dataset.owned)next.owned[t.dataset.owned]=p;else{const[i,j]=t.dataset.slot.split(':');next.current[mode][i][j].power=p}persist(next);if(t.dataset.slot){const sum=document.querySelector('.summary strong');if(sum)sum.textContent=fmt(total(state.current[mode]));const extra=document.querySelector('#formationExtras');if(extra)extra.innerHTML=formationExtras(state.current[mode],byId)}}}if(e.target.id==='search'){filters.q=e.target.value;$('#results').innerHTML=catalogContent()}});
document.addEventListener('change',async e=>{const t=e.target;try{if(['rarity','attribute','ownedOnly'].includes(t.id)){if(t.id==='ownedOnly')filters.owned=t.checked;else filters[t.id]=t.value;$('#results').innerHTML=catalogContent()}if(t.dataset.select){if(t.checked)selected.add(t.dataset.select);else selected.delete(t.dataset.select)}if(t.dataset.owned||t.dataset.slot){const p=Number(t.value);if(!powerOK(p)){t.value=t.dataset.owned?state.owned[t.dataset.owned]:state.current[mode][t.dataset.slot.split(':')[0]][t.dataset.slot.split(':')[1]].power;throw Error('戦力は1〜9999の整数で入力してください')}if(t.dataset.owned)mutate(s=>s.owned[t.dataset.owned]=p);else{const[i,j]=t.dataset.slot.split(':');mutate(s=>s.current[mode][i][j].power=p)}}if(t.id==='restoreFile'){const f=t.files[0];if(!f)return;if(f.size>8000000)throw Error('ファイルが大きすぎます');const next=validState(JSON.parse(await f.text()),ids);if(confirm('バックアップの内容でデータを置き換えますか？現在のデータを先に書き出すことをおすすめします。')){if(persist(next)){selected.clear();render();toast('復元しました')}}}}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='saveForm'){const name=new FormData(e.target).get('name').trim();if(!name)throw Error('ビルド名を入力してください');mutate(s=>s.builds.push({id:crypto.randomUUID(),name,mode,squads:clone(s.current[mode]),updatedAt:new Date().toISOString()}));$('#modal').close();toast('ビルドを保存しました')}if(e.target.id==='linkForm'){const url=new FormData(e.target).get('url');const token=url.includes('#share=')?url.split('#share=')[1]:url;shared=await decodeShare(token,ids);view='formation';tab='shared';$('#modal').close();render()}}catch(err){toast(err.message)}});
async function readHash(){if(location.hash.startsWith('#share=')){try{shared=await decodeShare(location.hash.slice(7),ids);view='formation';tab='shared';render()}catch(err){toast('共有リンクを読み込めません：'+err.message)}}}
try{const r=await fetch('./data/cards.json');if(!r.ok)throw Error('カードDBを取得できません');const data=await r.json();cards=data.cards;byId=new Map(cards.map(c=>[c.id,c]));ids=new Set(byId.keys());state=fresh();const raw=localStorage.getItem(KEY);if(raw){try{state=validState(JSON.parse(raw),ids)}catch{toast('保存データを読み込めません。データは上書きしていません。バックアップを確認してください。');$('#app').innerHTML='<h1>保存データの確認が必要です</h1><p>既存データの形式が正しくないため、上書きを防いでいます。</p>'+btn('元のデータを書き出す','recover');document.addEventListener('click',e=>{if(e.target.dataset.action==='recover')download('todiva-recovery.json',JSON.parse(raw))});throw Error('保存データの確認が必要です')}}render();await readHash();window.addEventListener('hashchange',readHash)}catch(err){if(!state||!cards.length)$('#app').innerHTML=`<h1>読み込みに失敗しました</h1><p>${esc(err.message)}</p><button onclick="location.reload()">再読み込み</button>`}
